<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {parseChatDate} from './chatTime';
import {callDuration,type VoiceCall} from './callHistory';
type Call=VoiceCall & {waiting?:boolean};
type Signal={kind:string;call:Call;offer?:RTCSessionDescriptionInit;answer?:RTCSessionDescriptionInit;candidate?:RTCIceCandidateInit};
const props=defineProps<{userId:number;csrf:string;request:(path:string,method?:string,body?:any)=>Promise<any>;avatar:(id:number)=>string|null;online:boolean;historyActive?:boolean}>();
const emit=defineEmits<{open:[id:number];changed:[conversationId:number]}>();
const minimized=ref(false);
const waiting=ref<Signal|null>(null);
async function declineWaiting(){const event=waiting.value;if(!event)return;waiting.value=null;await props.request('/calls/'+event.call.id+'/finish','POST',{status:'rejected'});void loadHistory();}
async function acceptWaiting(){const event=waiting.value;if(!event||busy.value)return;waiting.value=null;reset();call.value=event.call;offer.value=event.offer||null;for(const queued of early.get(event.call.id)||[]){if(queued.kind==='candidate'&&queued.candidate)incomingCandidates.push(queued.candidate);}early.delete(event.call.id);await accept();}

function preferredDevice(kind:string){try{return localStorage.getItem('judibas.call.'+kind)??'communications';}catch{return 'communications';}}
function saveDevice(kind:string,id:string){try{localStorage.setItem('judibas.call.'+kind,id);}catch{}}
const microphoneId=ref(preferredDevice('microphone')),speakerId=ref(preferredDevice('speaker'));
const call=ref<Call|null>(null),offer=ref<RTCSessionDescriptionInit|null>(null),busy=ref(false),error=ref(''),muted=ref(false),missedUnread=ref(0),history=ref<Call[]>([]),nextPage=ref<number|null>(null),historyBusy=ref(false),remoteAudio=ref<HTMLAudioElement|null>(null),audioBlocked=ref(false),clock=ref(Date.now());
let peer:RTCPeerConnection|null=null,local:MediaStream|null=null,remote:MediaStream|null=null,timeout:ReturnType<typeof setTimeout>|undefined,health:ReturnType<typeof setInterval>|undefined,clockTimer:ReturnType<typeof setInterval>|undefined,dead=false;
let historyDirty=false;
let toneAudio:AudioContext|null=null,toneTimer:ReturnType<typeof setInterval>|undefined;
function stopTone(){if(toneTimer)clearInterval(toneTimer);toneTimer=undefined;void toneAudio?.close().catch(()=>{});toneAudio=null;}
function ring(){if(toneTimer){void toneAudio?.resume().catch(()=>{});return;}try{toneAudio=new AudioContext();void toneAudio.resume().catch(()=>{});const beep=()=>{if(!toneAudio||toneAudio.state!=='running')return;for(const offset of [0,.35]){const oscillator=toneAudio.createOscillator(),gain=toneAudio.createGain();oscillator.frequency.value=480;gain.gain.value=.04;oscillator.connect(gain);gain.connect(toneAudio.destination);oscillator.start(toneAudio.currentTime+offset);oscillator.stop(toneAudio.currentTime+offset+.22);}};beep();toneTimer=setInterval(beep,2200);}catch{}}
const early=new Map<string,Signal[]>();let incomingCandidates:RTCIceCandidateInit[]=[],outgoingCandidates:RTCIceCandidateInit[]=[];
const incoming=computed(()=>call.value?.callee_id===props.userId&&call.value.status==='ringing');
const otherName=computed(()=>call.value?.caller_id===props.userId?call.value?.callee_name:call.value?.caller_name);
const otherId=computed(()=>call.value?.caller_id===props.userId?call.value?.callee_id:call.value?.caller_id);
function duration(c:Call){return callDuration(c,clock.value);}
const label=computed(()=>incoming.value?'Incoming voice call':call.value?.status==='ringing'?(call.value.waiting?'On another call':'Calling...'):call.value?.status==='active'?duration(call.value):'Connecting...');
function reset(){stopTone();minimized.value=false;if(timeout)clearTimeout(timeout);if(health)clearInterval(health);peer?.close();peer=null;local?.getTracks().forEach(t=>t.stop());local=null;remote=null;call.value=null;offer.value=null;incomingCandidates=[];outgoingCandidates=[];muted.value=false;audioBlocked.value=false;busy.value=false;}
async function signal(kind:string,data:Record<string,any>={}){const id=call.value?.id;if(!id)return;return props.request('/calls/'+id+'/signal','POST',{kind,...data});}
async function drainCandidates(){if(!peer?.remoteDescription)return;for(const candidate of incomingCandidates.splice(0))await peer.addIceCandidate(candidate);}
async function play(){await nextTick();if(remoteAudio.value&&remote){remoteAudio.value.srcObject=remote;remoteAudio.value.muted=false;remoteAudio.value.volume=1;try{const output=remoteAudio.value as HTMLAudioElement&{setSinkId?:(id:string)=>Promise<void>};if(output.setSinkId){try{await output.setSinkId(speakerId.value);}catch(e){if(!['NotFoundError','OverconstrainedError'].includes((e as DOMException).name))throw e;speakerId.value='';await output.setSinkId('');}saveDevice('speaker',speakerId.value);}await remoteAudio.value.play();audioBlocked.value=false;}catch{audioBlocked.value=true;}}}
function busyTone(){try{const context=new AudioContext();void context.resume().then(()=>{for(const offset of [0,.25,.5]){const oscillator=context.createOscillator(),gain=context.createGain();oscillator.frequency.value=425;gain.gain.value=.05;oscillator.connect(gain);gain.connect(context.destination);oscillator.start(context.currentTime+offset);oscillator.stop(context.currentTime+offset+.15);if(offset===.5)oscillator.onended=()=>{void context.close();};}}).catch(()=>{void context.close();});}catch{}}
function captureConstraints():MediaStreamConstraints{return {audio:{...(microphoneId.value?{deviceId:{exact:microphoneId.value}}:{}),echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false};}
async function setup(){
 if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)throw new Error('Voice calls need HTTPS (or localhost), a supported browser and microphone access.');
 const ice=await props.request('/calls/ice');
 try{local=await navigator.mediaDevices.getUserMedia(captureConstraints());}catch(e){if(!microphoneId.value||!['NotFoundError','OverconstrainedError'].includes((e as DOMException).name))throw e;microphoneId.value='';local=await navigator.mediaDevices.getUserMedia(captureConstraints());}
 saveDevice('microphone',microphoneId.value);
 microphoneId.value=local.getAudioTracks()[0]?.getSettings().deviceId||microphoneId.value;
 if(dead){local.getTracks().forEach(t=>t.stop());throw new Error('Call cancelled.');}
 peer=new RTCPeerConnection({iceServers:ice.iceServers});remote=new MediaStream();local.getTracks().forEach(t=>peer!.addTrack(t,local!));
 peer.ontrack=e=>{if(!remote?.getTracks().some(t=>t.id===e.track.id))remote?.addTrack(e.track);e.track.onunmute=()=>{void play();};void play();};
 peer.onicecandidate=e=>{if(!e.candidate)return;const candidate=e.candidate.toJSON();if(call.value)void signal('candidate',{candidate}).catch(()=>{});else outgoingCandidates.push(candidate);};
 peer.onconnectionstatechange=()=>{const state=peer?.connectionState;if(state==='connected'){void play();if(timeout)clearTimeout(timeout);void signal('connected').catch(e=>{error.value=(e as Error).message;void finish('failed');});}else if(state==='failed')void finish('failed');else if(state==='disconnected'){if(timeout)clearTimeout(timeout);timeout=setTimeout(()=>{if(peer?.connectionState!=='connected')void finish('failed');},15000);}};
}
function watchdog(){if(timeout)clearTimeout(timeout);timeout=setTimeout(()=>{if(call.value?.status==='ringing'){if(call.value.caller_id===props.userId)void finish('missed');else{reset();void sync();}}else if(call.value?.status==='connecting')void finish('failed');},call.value?.status==='ringing'?Math.max(1000,60000-(Date.now()-parseChatDate(call.value.created_at).getTime())):45000);if(health)clearInterval(health);health=setInterval(()=>{if(call.value&&['connecting','active'].includes(call.value.status))void signal('heartbeat').catch(()=>{error.value='Calling connection lost.';void finish('failed');});},25000);}
async function start(conversationId:number){if(call.value||busy.value)return;error.value='';busy.value=true;ring();try{if(!props.online)throw new Error('Reconnect to chat before starting a call.');await setup();const description=await peer!.createOffer();await peer!.setLocalDescription(description);const result=await props.request('/calls','POST',{conversation_id:conversationId,type:'audio',offer:{type:'offer',sdp:peer!.localDescription!.sdp}});if(dead){await props.request('/calls/'+result.call.id+'/finish','POST',{status:'failed'});reset();return;}if(result.call.status==='busy'){reset();error.value='This person is busy on another call. Try again later.';busyTone();emit('changed',result.call.conversation_id);void loadHistory();return;}call.value=result.call;emit('changed',result.call.conversation_id);ring();for(const candidate of outgoingCandidates.splice(0))await signal('candidate',{candidate}).catch(()=>{});if(call.value?.id===result.call.id)watchdog();for(const event of early.get(result.call.id)||[])await receive(event);early.delete(result.call.id);}catch(e){error.value=mediaError(e);if(call.value)await finish('failed');else reset();}finally{busy.value=false;}}
function mediaError(e:unknown){const name=(e as DOMException).name;return name==='NotAllowedError'?'Microphone permission was denied. Allow microphone access in your browser.':name==='NotFoundError'?'No microphone was found. Connect a microphone and try again.':(e as Error).message||'Unable to start the voice call.';}
async function accept(){if(!incoming.value||busy.value||!offer.value)return;busy.value=true;error.value='';stopTone();try{await setup();await peer!.setRemoteDescription(offer.value);await drainCandidates();const answer=await peer!.createAnswer();await peer!.setLocalDescription(answer);const result=await signal('answer',{answer:{type:'answer',sdp:peer!.localDescription!.sdp}});call.value=result.call;watchdog();}catch(e){const message=mediaError(e);if(message.includes('already answered')||message.includes('expired'))reset();else await finish('failed');error.value=message;}finally{busy.value=false;}}
async function finish(status?:string){const c=call.value;if(!c)return;const chosen=status||(c.status==='ringing'?(c.caller_id===props.userId?'cancelled':'rejected'):'ended');reset();try{await props.request('/calls/'+c.id+'/finish','POST',{status:chosen});emit('changed',c.conversation_id);await loadHistory();}catch(e){error.value=(e as Error).message;}}
async function receive(event:Signal){if(dead)return;const c=event.call;if(!c||![c.caller_id,c.callee_id].includes(props.userId))return;
 if(event.kind==='finished'&&waiting.value?.call.id===c.id)waiting.value=null;
 if(event.kind==='finished'||event.kind==='history_read'){emit('changed',c.conversation_id);void loadHistory();if(event.kind==='history_read')return;}

 if(event.kind==='incoming'){if(c.callee_id!==props.userId)return;if(call.value&&call.value.id!==c.id){waiting.value=event;minimized.value=false;busyTone();return;}call.value=c;emit('changed',c.conversation_id);offer.value=event.offer||null;ring();watchdog();return;}
 if(call.value?.id!==c.id){const list=early.get(c.id)||[];if(list.length<100)list.push(event);early.set(c.id,list);if(early.size>5)early.delete(early.keys().next().value!);return;}
 if(event.kind==='finished'){const pending=waiting.value;waiting.value=null;reset();if(pending)await receive(pending);return;}
 if(event.kind==='candidate'&&event.candidate){incomingCandidates.push(event.candidate);try{await drainCandidates();}catch{error.value='Unable to connect the voice call.';}return;}
 if(event.kind==='answer'&&event.answer&&peer){stopTone();try{call.value=c;await peer.setRemoteDescription(event.answer);await drainCandidates();watchdog();}catch(e){error.value=mediaError(e);await finish('failed');}return;}
 if(event.kind==='connected'){stopTone();call.value=c;emit('changed',c.conversation_id);}
}
async function sync(){if(busy.value)return;try{const state=await props.request('/calls/state');if(busy.value)return;if(!state.call){if(call.value)reset();return;}if(call.value?.id===state.call.id){call.value=state.call;waiting.value=state.waiting?{kind:'incoming',...state.waiting}:null;return;}if(state.call.callee_id===props.userId&&state.call.status==='ringing'){await receive({kind:'incoming',call:state.call,offer:state.offer});for(const event of early.get(state.call.id)||[])await receive(event);early.delete(state.call.id);}else await props.request('/calls/'+state.call.id+'/finish','POST',{status:'failed'});}catch(e){error.value=(e as Error).message;}}
async function loadHistory(older=false){if(historyBusy.value){historyDirty=true;return;}historyBusy.value=true;try{const result=await props.request('/calls'+(older&&nextPage.value?'?page='+nextPage.value:''));history.value=older?[...history.value,...result.calls.filter((c:Call)=>!history.value.some(x=>x.id===c.id))]:result.calls;nextPage.value=result.next_page;missedUnread.value=result.missed_unread||0;if(props.historyActive)await markRead();}catch(e){error.value=(e as Error).message;}finally{historyBusy.value=false;if(historyDirty&&!dead){historyDirty=false;void loadHistory();}}}
async function markRead(){const ids=history.value.filter(c=>c.callee_id===props.userId&&c.unread).map(c=>c.id);if(!ids.length)return;for(let i=0;i<ids.length;i+=30)await props.request('/calls/read','POST',{ids:ids.slice(i,i+30)});history.value.forEach(c=>{if(ids.includes(c.id))c.unread=false;});missedUnread.value=Math.max(0,missedUnread.value-ids.length);}
function mute(){muted.value=!muted.value;local?.getAudioTracks().forEach(t=>t.enabled=!muted.value);}
function unload(){const c=call.value;if(c)void fetch('/communication/api/calls/'+c.id+'/finish',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':props.csrf},body:JSON.stringify({status:c.status==='ringing'?(c.caller_id===props.userId?'cancelled':'rejected'):'ended'})}).catch(()=>{});reset();}
watch(remoteAudio,element=>{if(element&&remote)void play();});
watch(()=>props.historyActive,value=>{if(value)void loadHistory();});
watch(()=>props.online,value=>{if(value){void sync();void loadHistory();}});
onMounted(()=>{void sync();void loadHistory();clockTimer=setInterval(()=>clock.value=Date.now(),1000);window.addEventListener('pagehide',unload);});
onBeforeUnmount(()=>{dead=true;unload();if(clockTimer)clearInterval(clockTimer);window.removeEventListener('pagehide',unload);});
defineExpose({start,receive,sync,loadHistory,history,historyBusy,nextPage,missedUnread,busy,call});
</script>
<template>
<p v-if="error" class="voice-error" role="alert">{{error}} <button @click="error=''" aria-label="Dismiss calling error">&times;</button></p>
<Teleport to="body"><section v-if="call" class="voice-overlay" :class="{minimized}" role="dialog" :aria-modal="!minimized" aria-label="Voice call"><div class="voice-card" :class="{ringing:call.status==='ringing'}"><div class="voice-card-heading"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3 4 7v6c0 5 8 8 8 8s8-3 8-8V7l-8-4Z"/></svg><span>Judibas &middot; Voice call</span></div><button v-if="!incoming" class="voice-minimize" :aria-label="minimized?'Restore voice call':'Minimize voice call'" @click="minimized=!minimized"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path v-if="minimized" d="M8 16 16 8M8 8h8v8"/><path v-else d="m8 8 8 8m-8 0h8V8"/></svg></button><span class="voice-avatar"><img v-if="otherId&&avatar(otherId)" :src="avatar(otherId)!" alt=""><template v-else>{{otherName?.slice(0,1)}}</template></span><h2>{{otherName}}</h2><div class="voice-state"><span class="voice-state-dot"></span>{{call.status==='active'?(muted?'Microphone muted':'Connected'):incoming?'Incoming call':call.status==='ringing'?(call.waiting?'On another call':'Calling'):'Connecting'}}</div><p class="voice-duration" aria-live="polite">{{label}}</p><div v-if="waiting" class="voice-waiting"><strong>{{waiting.call.caller_name}}</strong><p>Incoming call while you are on another call</p><button :disabled="busy" @click="declineWaiting">Decline</button><button :disabled="busy" @click="acceptWaiting">End current &amp; accept</button></div><audio ref="remoteAudio" autoplay playsinline/><button v-if="audioBlocked" @click="play">Enable call audio</button><div class="voice-controls"><button v-if="incoming" class="voice-accept" :disabled="busy" @click="accept"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2z"/></svg><span>{{busy?'Connecting...':'Accept'}}</span></button><button v-if="!incoming&&call.status!=='ringing'" class="voice-mute" :class="{muted}" :aria-pressed="muted" :aria-label="muted?'Unmute':'Mute microphone'" @click="mute"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/><path v-if="muted" d="m3 3 18 18"/></svg><span>{{muted?'Unmute':'Mute'}}</span></button><button class="voice-end" :disabled="busy" :aria-label="incoming?'Decline':call.status==='ringing'?'Cancel':'End call'" @click="finish()"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M3 14v-3c4-5 14-5 18 0v3l-5-1v-3M3 14l5-1v-3"/></svg><span>{{incoming?'Decline':call.status==='ringing'?'Cancel':'End call'}}</span></button></div></div></section>
</Teleport>
</template>
<style scoped>
.voice-waiting{margin-top:20px;padding:16px;border:1px solid var(--line);border-radius:16px;background:rgba(18,169,126,.08)}.voice-waiting p{font-size:12px;color:var(--muted)}.voice-waiting button{padding:9px 12px;margin:4px;border-radius:8px;background:#138b72;color:white}.voice-error{position:fixed;top:76px;right:20px;max-width:420px;z-index:140;background:#572e2e;color:#fff;padding:12px 16px;border-radius:10px}.voice-error button{margin-left:12px}
.voice-overlay{position:fixed;inset:0;z-index:130;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(0,0,0,.65);backdrop-filter:blur(8px)}
.voice-card{position:relative;width:min(420px,100%);text-align:center;padding:24px 32px 30px;border-radius:28px;border:1px solid var(--line,#34433e);color:var(--text,#f2f5f4);background:radial-gradient(ellipse at 50% 18%,rgba(25,158,125,.18),transparent 62%),var(--rail,#202722);box-shadow:0 32px 100px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.04)}
.voice-card-heading{display:flex;align-items:center;gap:7px;color:var(--muted,#9baaa4);font-size:11px;letter-spacing:.3px;text-align:left}.voice-card-heading svg{color:#19b990}.voice-minimize{position:absolute;top:15px;right:16px;display:grid;place-items:center;width:34px;height:34px;padding:0;border:0;border-radius:50%;background:rgba(128,128,128,.12);color:var(--muted,#a9bab2);cursor:pointer}.voice-minimize:hover{background:rgba(128,128,128,.25)}
.voice-avatar{position:relative;display:inline-flex;align-items:center;justify-content:center;width:116px;height:116px;margin:40px 0 0;border-radius:50%;background:linear-gradient(145deg,#1b6657,#13382f);color:#68dfbc;font-size:44px;font-weight:500;border:5px solid rgba(100,192,160,.12);box-shadow:0 0 0 9px rgba(83,169,141,.07),0 12px 36px rgba(0,0,0,.15);overflow:hidden}.voice-avatar img{width:100%;height:100%;object-fit:cover}.ringing .voice-avatar{animation:voice-ring 2s ease-out infinite}.voice-card h2{margin:26px 0 12px;font-family:inherit;font-size:27px;font-weight:600;letter-spacing:-.6px;line-height:1.25;overflow-wrap:anywhere}
.voice-state{display:inline-flex;align-items:center;gap:7px;padding:5px 11px;border-radius:20px;background:rgba(18,169,126,.1);color:#16ad87;font-size:11px;font-weight:500}.voice-state-dot{height:5px;width:5px;border-radius:50%;background:currentColor}.voice-card .voice-duration{margin:14px 0 0;font-size:20px;font-variant-numeric:tabular-nums;letter-spacing:1px;color:var(--muted,#9baaa4)}
.voice-card .voice-controls{display:flex;align-items:flex-start;justify-content:center;gap:28px;margin:36px 0 0}.voice-card .voice-controls button{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:12px;min-width:76px;padding:0;border:0;border-radius:0;background:transparent;color:var(--text,#f2f5f4);font-size:12px;font-weight:400;cursor:pointer}.voice-controls button svg{display:block;box-sizing:content-box;flex-shrink:0;padding:18px;border:1px solid rgba(128,128,128,.2);border-radius:50%;background:rgba(128,128,128,.13);transition:transform .18s,background .18s}.voice-controls button:hover svg{transform:translateY(-2px);background:rgba(128,128,128,.25)}.voice-controls .voice-end svg{background:#ec485d;border-color:#ec485d;color:#fff;box-shadow:0 6px 20px rgba(236,72,93,.22)}.voice-controls .voice-end:hover svg{background:#df334b}.voice-controls .voice-accept svg{background:#0cad83;border-color:#0cad83;color:#fff;box-shadow:0 6px 20px rgba(12,173,131,.2)}.voice-controls .voice-mute.muted svg{background:var(--text,#eee);color:var(--rail,#222)}.voice-controls button:disabled{opacity:.5;cursor:wait}.voice-controls button:focus-visible,.voice-minimize:focus-visible{outline:2px solid #25be97;outline-offset:5px}
.voice-overlay.minimized{inset:auto 18px 18px auto;padding:0;background:transparent;backdrop-filter:none;width:min(310px,calc(100vw - 36px))}.minimized .voice-card{padding:18px 20px 22px;border-radius:22px}.minimized .voice-card-heading{font-size:10px}.minimized .voice-avatar{width:52px;height:52px;margin-top:20px;font-size:23px;border-width:3px;box-shadow:0 0 0 5px rgba(83,169,141,.07)}.minimized .voice-card h2{font-size:18px;margin:15px 0 10px}.minimized .voice-duration{font-size:16px;margin-top:10px}.minimized .voice-card .voice-controls{margin-top:20px;gap:22px}.minimized .voice-controls button svg{width:20px;height:20px;padding:12px}.minimized .voice-controls button{font-size:11px;gap:8px;min-width:64px}
@keyframes voice-ring{0%,100%{box-shadow:0 0 0 9px rgba(83,169,141,.07)}50%{box-shadow:0 0 0 17px rgba(83,169,141,.03)}}@media(prefers-reduced-motion:reduce){.ringing .voice-avatar{animation:none}.voice-controls button svg{transition:none}}@media(max-width:480px){.voice-overlay{padding:16px}.voice-card{padding:22px 22px 28px}.voice-avatar{margin-top:34px}.voice-card h2{font-size:24px}}
</style>
